/bin/bash -lc "node <<'NODE'
const fs = require('fs');
const path = '/home/user/.config/google-chrome/Local State';
const backup = "'`${path}.before-disable-refresh-2023`;
if (!fs.existsSync(backup)) fs.copyFileSync(path, backup);
const state = JSON.parse(fs.readFileSync(path, '"'utf8'));
state.browser = state.browser || {};
const disabled = [
  'chrome-refresh-2023@2',
  'chrome-webui-refresh-2023@2',
  'chrome-refresh-2023-ntb@2',
  'chrome-refresh-2023-top-chrome-font@2'
];
const names = new Set(disabled.map(x => x.split('@')[0]));
const existing = Array.isArray(state.browser.enabled_labs_experiments)
  ? state.browser.enabled_labs_experiments
  : [];
state.browser.enabled_labs_experiments = [
  ...existing.filter(item => "'!names.has(String(item).split('"'@')[0])),
  ...disabled
];
fs.writeFileSync(path, JSON.stringify(state));
console.log(state.browser.enabled_labs_experiments.filter(x => /chrome.*refresh.*2023|chrome-webui-refresh-2023/i.test(x)).join('\\n'));
NODE"

